func TestEnumResourceStatus(t *testing.T) {
	t.Run("NewFromString_ok", func(t *testing.T) {
		t.Parallel()
		val, err := NewResourceStatusFromString("ok")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ResourceStatus("ok"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_not_found", func(t *testing.T) {
		t.Parallel()
		val, err := NewResourceStatusFromString("not_found")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ResourceStatus("not_found"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_assigned", func(t *testing.T) {
		t.Parallel()
		val, err := NewResourceStatusFromString("assigned")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ResourceStatus("assigned"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_already_assigned", func(t *testing.T) {
		t.Parallel()
		val, err := NewResourceStatusFromString("already_assigned")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ResourceStatus("already_assigned"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_service_down", func(t *testing.T) {
		t.Parallel()
		val, err := NewResourceStatusFromString("service_down")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ResourceStatus("service_down"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewResourceStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewResourceStatusFromString("ok")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

func TestExtraPropertiesProjectAssignment(t *testing.T) {
	t.Run("GetExtraProperties", func(t *testing.T) {
		t.Parallel()
		obj := &ProjectAssignment{}
		// Should not panic when calling GetExtraProperties()
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("GetExtraProperties() panicked: %v", r)
			}
		}()
		extraProps := obj.GetExtraProperties()
		// Result can be nil or an empty/non-empty map
		_ = extraProps
	})

	t.Run("GetExtraProperties_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *ProjectAssignment
		extraProps := obj.GetExtraProperties()
		assert.Nil(t, extraProps, "nil receiver should return nil without panicking")
	})
}

